// @vitest-environment node
// MFW-66: the committed house model module (generated by scripts/house-model.mjs from the owner file) and its docs.
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { CAMERA_FLIGHT_OFFSET } from "@/config/camera.config";
import { LOY_KRATHONG_HOUSE_MODEL as M } from "@/config/events/loyKrathong.houseModel";
import { LOOK_MIN_ALBEDO_LUMINANCE, LOOK_PALETTE } from "@/config/look.config";
import { HOUSE_MODEL_MAX_TRIANGLES } from "@/config/performance.config";
import type { StaticPartMesh } from "@/config/scene.config";
import { relativeLuminance } from "@/core/math/relativeLuminance";
import { HOUSE_MODEL_SPEC } from "../../scripts/house-model.data.mjs";

const SOURCE_SHA256 = "cead59093e07cdcf6112748716dad9dbadc6ae1c177f3bd13b0c27572cda9722";
const ROOT = join(__dirname, "../..");
/** The procedural house envelope before MFW-66 (gable roof 0.92 × 0.72; roof top 0.65 + 0.15 + headroom). */
const OLD_GABLE = { width: 0.92, depth: 0.72 };
const MAX_TOP_Y = 0.85;

const triangles = (part: StaticPartMesh) => part.indices.length / 3;
const maxAbs = (part: StaticPartMesh, axis: number) => {
  let m = 0;
  for (let i = axis; i < part.positions.length; i += 3) m = Math.max(m, Math.abs(part.positions[i]));
  return m;
};

describe("owner house model asset (MFW-66)", () => {
  it("HA1: the module records the owner source and the generator", () => {
    expect(M.source.sha256).toBe(SOURCE_SHA256);
    expect(M.source.generator).toBe("mfw scripts/house-model.mjs");
  });

  it("HA2: triangles per part stay within HOUSE_MODEL_MAX_TRIANGLES", () => {
    expect(triangles(M.shell)).toBeGreaterThan(0);
    expect(triangles(M.roof)).toBeGreaterThan(0);
    expect(triangles(M.shell)).toBeLessThanOrEqual(HOUSE_MODEL_MAX_TRIANGLES.shell);
    expect(triangles(M.roof)).toBeLessThanOrEqual(HOUSE_MODEL_MAX_TRIANGLES.roof);
    for (const part of [M.shell, M.roof]) {
      expect(part.indices.length % 3).toBe(0);
      for (const i of part.indices) expect(i).toBeLessThan(part.positions.length / 3);
    }
  });

  it("HA3: every shell colour is a LOOK_PALETTE clay pastel colour of the spec palette, light enough", () => {
    const entries = Object.values(HOUSE_MODEL_SPEC.palette);
    expect(M.shell.palette.length).toBeGreaterThan(0);
    for (const hex of M.shell.palette) {
      const entry = entries.find((e) => e.hex === hex);
      expect(entry, hex).toBeDefined();
      expect(LOOK_PALETTE[entry!.key as keyof typeof LOOK_PALETTE], hex).toBe(hex);
      expect(relativeLuminance(hex), hex).toBeGreaterThanOrEqual(LOOK_MIN_ALBEDO_LUMINANCE);
    }
    expect(M.shell.faceColors).not.toBeNull();
    expect(M.shell.faceColors).toHaveLength(triangles(M.shell));
    for (const c of M.shell.faceColors ?? []) expect(c).toBeLessThan(M.shell.palette.length);
    expect(M.roof.faceColors).toBeNull();
    expect(M.roof.palette).toEqual([]);
  });

  it("HA4: half extents match the positions and stay inside the old house envelope", () => {
    for (const part of [M.shell, M.roof]) {
      for (let a = 0; a < 3; a++) expect(Math.abs(part.halfExtents[a] - maxAbs(part, a))).toBeLessThanOrEqual(1e-9);
      expect(2 * part.halfExtents[0]).toBeLessThanOrEqual(OLD_GABLE.width);
      expect(2 * part.halfExtents[2]).toBeLessThanOrEqual(OLD_GABLE.depth);
      expect(part.centerY + part.halfExtents[1]).toBeLessThanOrEqual(MAX_TOP_Y);
    }
  });

  it("HA5: five window glasses (2 front, 2 back, 1 side) inside the shell, above the ground", () => {
    expect(M.windows).toHaveLength(5);
    const yaws = M.windows.map((w) => w.yawRad);
    [0, 0, Math.PI, Math.PI, Math.PI / 2].forEach((y, i) => expect(Math.abs(yaws[i] - y)).toBeLessThanOrEqual(1e-9));
    const [hx, hy, hz] = M.shell.halfExtents;
    for (const w of M.windows) {
      expect(Math.abs(w.x)).toBeLessThanOrEqual(hx);
      expect(Math.abs(w.z)).toBeLessThanOrEqual(hz);
      expect(w.y).toBeGreaterThanOrEqual(M.shell.centerY - hy);
      expect(w.y).toBeLessThanOrEqual(M.shell.centerY + hy);
      expect(w.y - M.glass.height / 2).toBeGreaterThan(0);
    }
    expect(M.glass.depth).toBe(HOUSE_MODEL_SPEC.glassDepth);
  });

  it("HA6: the door is at the front (local +Z)", () => {
    const door = M.shell.palette.indexOf(LOOK_PALETTE.doorWood);
    expect(door).toBeGreaterThanOrEqual(0);
    let doorFaces = 0;
    M.shell.faceColors!.forEach((c, f) => {
      if (c !== door) return;
      doorFaces += 1;
      let z = 0;
      for (let k = 0; k < 3; k++) z += M.shell.positions[M.shell.indices[f * 3 + k] * 3 + 2] / 3;
      expect(z, `door face ${f}`).toBeGreaterThan(0.25);
    });
    expect(doorFaces).toBeGreaterThan(0);
  });

  it("HA7: down faces are culled only past the fixed camera elevation", () => {
    const [x, y, z] = CAMERA_FLIGHT_OFFSET;
    expect(HOUSE_MODEL_SPEC.downFaceMaxNormalY).toBeLessThanOrEqual(-Math.hypot(x, z) / Math.hypot(x, y, z));
  });

  it("HA9: MFW-77: the lite shell (LOW) is lighter than the shell, with the same palette, frame and a box inside it", () => {
    const L = M.liteShell;
    expect(triangles(L)).toBeGreaterThan(0);
    expect(triangles(L)).toBeLessThanOrEqual(HOUSE_MODEL_MAX_TRIANGLES.liteShell);
    expect(triangles(L)).toBeLessThan(triangles(M.shell));
    expect(L.indices.length % 3).toBe(0);
    for (const i of L.indices) expect(i).toBeLessThan(L.positions.length / 3);
    expect(L.palette).toEqual(M.shell.palette);
    expect(L.centerY).toBe(M.shell.centerY);
    for (let a = 0; a < 3; a++) expect(L.halfExtents[a]).toBeLessThanOrEqual(M.shell.halfExtents[a] + 1e-9);
  });

  it("HA8: docs/design/models.md records the source, the owner's licence note and the screenshots", () => {
    const doc = readFileSync(join(ROOT, "docs/design/models.md"), "utf8");
    expect(doc).toContain(SOURCE_SHA256);
    expect(doc).toContain("MFW-66");
    expect(doc).toContain("ใช้ได้แต่ไม่ใช้เชิงพาณิชย์");
    for (const when of ["before", "after"])
      for (const preset of ["day", "night"])
        expect(existsSync(join(ROOT, `docs/design/screenshots/mfw-66/${when}-world-${preset}.png`)), `${when} ${preset}`).toBe(true);
  });
});
